import { SEARCH_BAR_HEIGHT } from '@/constants'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { SearchIcon } from 'lucide-react-native'
import { Text, TextInput } from 'react-native'
import React from 'react'
import { LiquidGlassView } from '../LiquidGlassView'

type LiquidGlassSearchBarProps =
	| {
			searchInputRef?: React.RefObject<TextInput | null>
			setIsSearchBarOpen: (isSearchBarOpen: boolean) => void
			isButton: true
			searchValue: string
			placeholder: string
	  }
	| {
			searchInputRef?: React.RefObject<TextInput | null>
			setIsSearchBarOpen: (isSearchBarOpen: boolean) => void
			isButton: false
			searchValue: string
			placeholder: string
			setSearchValue: (searchValue: string) => void
			addSearchToHistory: (searchValue: string) => void
	  }

export const LiquidGlassSearchBar = (props: LiquidGlassSearchBarProps) => {
	const {
		searchInputRef,
		setIsSearchBarOpen,
		isButton,
		searchValue,
		placeholder
	} = props
	const setSearchValue = !isButton ? props.setSearchValue : undefined
	const addSearchToHistory = !isButton ? props.addSearchToHistory : undefined
	const { theme } = useTheme()

	const handleChangeText = (text: string) => {
		setSearchValue?.(text)
	}

	const handleFocus = () => {
		setIsSearchBarOpen(true)
	}

	const handleBlur = () => {
		setIsSearchBarOpen(false)
	}

	const handleSubmitEditing = () => {
		addSearchToHistory?.(searchValue || '')
	}

	return (
		<LiquidGlassView
			isInteractive={true}
			style={styles.liquidGlass}
			glassEffectStyle="regular"
		>
			<SearchIcon size={24} color={colors[theme].gray[900]} />
			{!isButton ? (
				<TextInput
					key="search-input"
					ref={searchInputRef}
					value={searchValue}
					onChangeText={handleChangeText}
					onFocus={handleFocus}
					onBlur={handleBlur}
					placeholder="Search in projects"
					placeholderTextColor={colors[theme].gray[200]}
					style={styles.textInput(theme)}
					onSubmitEditing={handleSubmitEditing}
				/>
			) : (
				<Text
					style={[
						styles.textInput(theme),
						styles.textInputLabelModified(theme),
						{
							color: searchValue
								? colors[theme].gray[900]
								: colors[theme].gray[200]
						}
					]}
				>
					{searchValue || placeholder || 'Search in projects'}
				</Text>
			)}
		</LiquidGlassView>
	)
}

const styles = defineStyles({
	liquidGlass: {
		flexDirection: 'row',
		justifyContent: 'flex-start',
		alignItems: 'center',
		gap: 12,
		paddingHorizontal: 20,
		width: '100%',
		height: SEARCH_BAR_HEIGHT,
		borderRadius: 28
	},
	nonLiquidGlass: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[50]
	}),
	searchBarContainer: {
		paddingHorizontal: 20,
		flexDirection: 'row',
		justifyContent: 'flex-start',
		alignItems: 'center',
		height: SEARCH_BAR_HEIGHT,
		gap: 12
	},
	textInput: (theme: Theme) => ({
		textAlign: 'left',
		fontSize: 18,
		fontWeight: '500',
		color: colors[theme].gray[900],
		width: '75%'
	}),
	fakeLiquidGlass: (theme: Theme, isDark: boolean) => ({
		borderRadius: 28,
		backgroundColor: isDark ? colors[theme].gray[100] : colors[theme].gray[50]
	}),
	nonLGTextInput: (theme: Theme, isDark: boolean) => ({
		color: isDark ? colors[theme].gray[700] : colors[theme].gray[200]
	}),
	textInputLabelModified: (theme: Theme) => ({
		color: colors[theme].gray[200]
	})
})
